    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('30100101-0000-4000-8000-000000000001', '65d29b56-2011-2001-0000-000000000001', 'Which pair of traits are strictly DEFINING features of all living organisms without any exception?', '{"A":"Metabolism and Cellular organisation","B":"Growth and Reproduction","C":"Intrinsic growth and Binary fission","D":"Locomotion and Photosynthetic nutrition"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Mules, sterile worker bees and infertile couples do not reproduce; mountains show extrinsic growth. Metabolism, cellular organisation & consciousness are defining.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000002', '65d29b56-2011-2001-0000-000000000001', 'According to ICBN binomial nomenclature, Mangifera indica Linn. indicates:', '{"A":"Mangifera is genus, indica is specific epithet, Linn. indicates Linnaeus first described it","B":"Linn. stands for Linnaeus variety","C":"Species name starts with a capital letter","D":"Printed italics signify English origin"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Genus starts with Capital, specific epithet lowercase, italicized for Latin origin, author abbreviation in Roman script.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000003', '65d29b56-2011-2001-0000-000000000002', 'Which extremophile Archaebacteria reside in marshy areas and the gut of ruminant animals producing biogas?', '{"A":"Methanogens","B":"Halophiles","C":"Thermoacidophiles","D":"Mycoplasma"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Methanogens occur in guts of cows/buffaloes and marshy swamps, generating methane.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000004', '65d29b56-2011-2001-0000-000000000002', 'Infectious free low-molecular-weight RNA lacking a protein coat discovered by T.O. Diener causing Potato Spindle Tuber Disease is:', '{"A":"Viroid","B":"Prion","C":"Bacteriophage","D":"Retrovirus"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Viroids are free RNA without capsid (1971, T.O. Diener); Prions are abnormally folded proteins.', 'EASY', 'NEET 2024', true),
    ('30100101-0000-4000-8000-000000000005', '65d29b56-2011-2001-0000-000000000002', 'Statement I: Mycoplasma completely lacks a cell wall and can survive without oxygen.\nStatement II: Fungi imperfecti (Deuteromycetes) show both sexual ascospores and asexual conidia.', '{"A":"Statement I is correct, Statement II is incorrect","B":"Both Statements I and II are correct","C":"Both Statements are incorrect","D":"Statement I is incorrect, Statement II is correct"}'::jsonb, 'A', 'STATEMENT', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Deuteromycetes reproduce ONLY by asexual conidia; once sexual forms are discovered they move to Ascomycetes/Basidiomycetes.', 'MEDIUM', 'NEET Statement Bank', true),
    ('30100101-0000-4000-8000-000000000006', '65d29b56-2011-2001-0000-000000000003', 'Which algal class stores food as Floridean starch and lacks flagellated motile stages completely?', '{"A":"Rhodophyceae (Red Algae)","B":"Phaeophyceae (Brown Algae)","C":"Chlorophyceae (Green Algae)","D":"Euglenoids"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Red algae (Polysiphonia, Gracilaria) have phycoerythrin, floridean starch (resembles amylopectin/glycogen) and zero flagella.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000007', '65d29b56-2011-2001-0000-000000000003', 'Heterosporous pteridophytes (producing both microspores and megaspores — precursor to seed habit) are:', '{"A":"Selaginella and Salvinia","B":"Equisetum and Pteris","C":"Marchantia and Funaria","D":"Pinus and Cycas"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Selaginella and Salvinia are classic NCERT heterosporous pteridophyte examples.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000008', '65d29b56-2011-2002-0000-000000000001', 'Axile placentation (multilocular ovary with ovules on central axis) is characteristic of:', '{"A":"China rose (Hibiscus), Tomato and Lemon","B":"Mustard and Argemone","C":"Dianthus and Primrose","D":"Sunflower and Marigold"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Axile = China rose/Tomato/Lemon; Parietal = Mustard/Argemone; Free-central = Dianthus/Primrose; Basal = Sunflower/Marigold.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000009', '65d29b56-2011-2002-0000-000000000002', '[NMC Added Family] Epicalyx, monoadelphous stamens forming a staminal tube, and reniform monothecous anthers belong to:', '{"A":"Malvaceae (China rose / Cotton)","B":"Cruciferae (Brassicaceae)","C":"Compositae (Asteraceae)","D":"Gramineae (Poaceae)"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Malvaceae features epicalyx, twisted corolla aestivation and monoadelphous stamens.', 'MEDIUM', 'NMC 2026 Syllabus', true),
    ('30100101-0000-4000-8000-000000000010', '65d29b56-2011-2002-0000-000000000002', '[NMC Added Family] Pappus-modified calyx, syngenesious stamens (anthers fused, filaments free) and cypsela fruit define:', '{"A":"Compositae (Asteraceae — Sunflower)","B":"Gramineae (Poaceae — Wheat)","C":"Leguminosae (Fabaceae)","D":"Cruciferae (Mustard)"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Asteraceae capitulum flowers possess hairy pappus calyx and syngenesious androecium.', 'MEDIUM', 'NMC 2026 Syllabus', true),
    ('30100101-0000-4000-8000-000000000011', '65d29b56-2011-2002-0000-000000000002', '[NMC Added Family] Cruciform corolla (4 clawed petals), tetradynamous stamens (2 short + 4 long) and replum false septum are found in:', '{"A":"Cruciferae (Brassicaceae — Mustard)","B":"Malvaceae","C":"Poaceae","D":"Fabaceae"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Brassicaceae features A2+4 tetradynamous stamens and bicarpellary ovary with false septum (replum).', 'MEDIUM', 'NMC 2026 Syllabus', true),
    ('30100101-0000-4000-8000-000000000012', '65d29b56-2011-2002-0000-000000000003', 'In grass (monocot) leaves, large empty colourless adaxial epidermal cells that curl leaves inward to minimize water loss are:', '{"A":"Bulliform cells","B":"Guard cells","C":"Companion cells","D":"Casparian strip cells"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Bulliform cells become flaccid during water stress, rolling grass leaves to lower transpiration.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000013', '65d29b56-2011-2002-0000-000000000003', 'Suberised waxy Casparian strips impermeable to water occur in which anatomical layer of dicot/monocot roots?', '{"A":"Endodermis","B":"Pericycle","C":"Hypodermis","D":"Epiblema"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Radial & tangential walls of root endodermal cells contain suberin Casparian strips.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000014', '65d29b56-2011-2003-0000-000000000001', 'Which organelle complex is the primary site for synthesis of glycoproteins and glycolipids in eukaryotic cells?', '{"A":"Golgi apparatus","B":"Smooth ER","C":"Peroxisome","D":"Vacuole tonoplast"}'::jsonb, 'A', 'MCQ', 'Botany', 'Cell Biology & Division', 4, 1.00, 'NMC_SYNCED', 'Golgi bodies package and glycosylate proteins/lipids received from ER.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000015', '65d29b56-2011-2003-0000-000000000001', 'Non-staining secondary constrictions at constant locations on specific human/plant chromosomes produce small fragments called:', '{"A":"Satellites (SAT-chromosomes)","B":"Kinetochores","C":"Telomeres","D":"Mesosomes"}'::jsonb, 'A', 'MCQ', 'Botany', 'Cell Biology & Division', 4, 1.00, 'NMC_SYNCED', 'Secondary constrictions (NOR) give rise to satellite fragments.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000016', '65d29b56-2011-2003-0000-000000000002', 'Dissolution of synaptonemal complex and appearance of X-shaped chiasmata occur during which substage of Prophase I?', '{"A":"Diplotene","B":"Zygotene","C":"Pachytene","D":"Leptotene"}'::jsonb, 'A', 'MCQ', 'Botany', 'Cell Biology & Division', 4, 1.00, 'NMC_SYNCED', 'Synapsis = Zygotene; Crossing over = Pachytene; Chiasmata visible = Diplotene; Terminalisation = Diakinesis.', 'EASY', 'NEET 2024', true),
    ('30100101-0000-4000-8000-000000000017', '65d29b56-2011-2003-0000-000000000002', 'If a diploid onion root tip cell has 2n = 16 chromosomes and 2C DNA at G1 phase, what are chromosome count & DNA content at G2 phase?', '{"A":"16 chromosomes, 4C DNA","B":"32 chromosomes, 4C DNA","C":"8 chromosomes, 2C DNA","D":"16 chromosomes, 2C DNA"}'::jsonb, 'A', 'MCQ', 'Botany', 'Cell Biology & Division', 4, 1.00, 'NMC_SYNCED', 'During S-phase, DNA replicates (2C -> 4C) while centromere count / chromosome number stays 16.', 'MEDIUM', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000018', '65d29b56-2011-2004-0000-000000000001', 'Statement I: In C4 plants (maize, sorghum), photorespiration does not occur because Kranz anatomy concentrates CO₂ at RuBisCO.\nStatement II: RuBisCO in C4 plants is located in mesophyll cells.', '{"A":"Statement I is correct, Statement II is incorrect","B":"Both Statements are correct","C":"Both Statements are incorrect","D":"Statement I is incorrect, Statement II is correct"}'::jsonb, 'A', 'STATEMENT', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'RuBisCO is exclusively in bundle sheath chloroplasts; mesophyll has PEPcase.', 'MEDIUM', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000019', '65d29b56-2011-2004-0000-000000000001', 'Reaction centre chlorophyll a molecules of Photosystem II (PS II) and Photosystem I (PS I) show absorption maxima respectively at:', '{"A":"680 nm (P680) and 700 nm (P700)","B":"700 nm and 680 nm","C":"430 nm and 660 nm","D":"720 nm and 680 nm"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'PS II = P680 (associated with water splitting); PS I = P700.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000020', '65d29b56-2011-2004-0000-000000000002', 'Which enzyme of Krebs cycle (Citric Acid Cycle) is located on the inner mitochondrial membrane rather than the matrix?', '{"A":"Succinate dehydrogenase (Complex II)","B":"Citrate synthase","C":"Isocitrate dehydrogenase","D":"Hexokinase"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'Succinate dehydrogenase doubles as Complex II of inner mitochondrial membrane ETS.', 'MEDIUM', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000021', '65d29b56-2011-2004-0000-000000000002', 'During complete aerobic oxidation of one glucose molecule, how many ATP molecules are generated in total (including glycolysis + Krebs + ETS)?', '{"A":"38 ATP (or 36 depending on shuttle)","B":"2 ATP","C":"12 ATP","D":"18 ATP"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'NCERT Respiration Ch 12 states net gain of 38 ATP per glucose in eukaryotes.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000022', '65d29b56-2011-2004-0000-000000000003', 'Which gaseous plant growth regulator induces "bolting" (internode elongation) — Wait carefully: which hormone causes bolting in beet/cabbage, vs triple response?', '{"A":"Gibberellic acid (GA) causes bolting; Ethylene causes triple response","B":"Abscisic acid causes bolting","C":"Auxin inhibits root growth","D":"Cytokinin induces stomatal closure"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'Gibberellins trigger bolting in rosette plants (beet, cabbages); Ethylene promotes horizontal seedling growth & fruit ripening.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000023', '65d29b56-2011-2004-0000-000000000003', 'Which hormone is called the "Stress Hormone" because it stimulates stomatal closure during drought conditions?', '{"A":"Abscisic Acid (ABA)","B":"Indole-3-acetic acid (IAA)","C":"Kinetin","D":"Ethephon"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'ABA acts as general plant growth inhibitor and closes stomata under water stress.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000024', '65d29b56-2011-2005-0000-000000000001', 'A mature typical angiosperm embryo sac at the time of fertilisation is:', '{"A":"7-celled and 8-nucleate","B":"8-celled and 7-nucleate","C":"7-celled and 7-nucleate","D":"8-celled and 8-nucleate"}'::jsonb, 'A', 'MCQ', 'Botany', 'Sexual Reproduction Plants', 4, 1.00, 'NMC_SYNCED', '3 antipodals (3 cells) + 1 large central cell (2 polar nuclei) + 2 synergids + 1 egg = 7 cells, 8 nuclei.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000025', '65d29b56-2011-2005-0000-000000000001', 'Which wall layer of a microsporangium nourishes developing pollen grains and typically possesses dense cytoplasm with >1 nucleus?', '{"A":"Tapetum","B":"Endothecium","C":"Epidermis","D":"Middle layer"}'::jsonb, 'A', 'MCQ', 'Botany', 'Sexual Reproduction Plants', 4, 1.00, 'NMC_SYNCED', 'Innermost wall layer tapetum nourishes pollen grains and secretes sporopollenin precursors.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000026', '65d29b56-2011-2005-0000-000000000002', 'Persistent diploid nucellus present in mature seeds of black pepper and beet is known as:', '{"A":"Perisperm","B":"Pericarp","C":"Scutellum","D":"Aleuroplasts"}'::jsonb, 'A', 'MCQ', 'Botany', 'Sexual Reproduction Plants', 4, 1.00, 'NMC_SYNCED', 'Residual persistent nucellus = Perisperm (Black pepper, Beet).', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000027', '65d29b56-2011-2005-0000-000000000002', 'In Citrus and Mango varieties, nucellar cells surrounding the embryo sac protrude and develop into multiple embryos. This phenomenon is:', '{"A":"Polyembryony (via nucellar apomixis)","B":"Parthenocarpy","C":"Triple fusion","D":"Geitonogamy"}'::jsonb, 'A', 'MCQ', 'Botany', 'Sexual Reproduction Plants', 4, 1.00, 'NMC_SYNCED', 'Polyembryony occurs naturally in Citrus & Mango when sporophytic nucellar cells divide into embryos.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000028', '65d29b56-2011-2006-0000-000000000001', 'Assertion (A): Snapdragon (Antirrhinum majus) shows 1:2:1 phenotypic ratio in F2 generation.\nReason (R): Flower colour inheritance in Snapdragon exhibits Incomplete Dominance.', '{"A":"Both A and R are true and R is the correct explanation of A","B":"Both A and R are true but R is NOT the correct explanation","C":"A is true, R is false","D":"A is false, R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'In incomplete dominance (RR red × rr white -> Rr pink), F2 gives 1 Red : 2 Pink : 1 White.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000029', '65d29b56-2011-2006-0000-000000000001', 'Which chromosomal disorder results from trisomy of chromosome 21 (47, +21)?', '{"A":"Down’s Syndrome","B":"Klinefelter’s Syndrome","C":"Turner’s Syndrome","D":"Phenylketonuria"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'Down’s = Trisomy 21; Klinefelter = 47, XXY; Turner = 45, XO.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000030', '65d29b56-2011-2006-0000-000000000001', 'In honeybees, drones (males) develop parthenogenetically from unfertilised eggs and therefore:', '{"A":"Are haploid (n = 16), produce sperm by mitosis, have no father and cannot have sons","B":"Are diploid 32 chromosomes","C":"Show XY sex determination","D":"Have diploid sons and haploid daughters"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'Haplodiploid mechanism: male bees have a grandfather and grandsons, never a father or sons!', 'MEDIUM', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000031', '65d29b56-2011-2006-0000-000000000002', 'In Meselson and Stahl’s experiment using ¹⁵N heavy isotope in E. coli, after two generations (40 mins) in ¹⁴NH₄Cl medium, DNA density bands observed were:', '{"A":"50% hybrid (¹⁵N-¹⁴N) and 50% light (¹⁴N-¹⁴N)","B":"100% hybrid DNA","C":"25% heavy and 75% light","D":"100% light DNA"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'Gen 1 (20 min): 100% hybrid; Gen 2 (40 min): 50% hybrid + 50% light (semiconservative).', 'MEDIUM', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000032', '65d29b56-2011-2006-0000-000000000002', 'If a double-stranded DNA contains 18% Guanine (G), calculate the percentage of Adenine (A) using Chargaff’s rule:', '{"A":"32 %","B":"18 %","C":"36 %","D":"64 %"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'G = C = 18% => G+C = 36% => A+T = 64% => A = 32%.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000033', '65d29b56-2011-2006-0000-000000000002', 'In eukaryotes, which RNA polymerase transcribes precursor of mRNA (hnRNA)?', '{"A":"RNA Polymerase II","B":"RNA Polymerase I","C":"RNA Polymerase III","D":"Primase"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'Pol I -> rRNA (28S, 18S, 5.8S); Pol II -> hnRNA/mRNA; Pol III -> tRNA, 5srRNA, snRNAs.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000034', '65d29b56-2011-2006-0000-000000000002', 'Which three codons act as STOP (nonsense) codons during mRNA translation and do NOT specify any amino acid?', '{"A":"UAA, UAG, UGA","B":"AUG, UGG, UAA","C":"UAA, GUA, UGA","D":"UUU, UAG, UGG"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'UAA, UAG, UGA terminate translation; AUG is start/Met.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000035', '65d29b56-2011-2007-0000-000000000001', 'Which population interaction (+ / 0) represents an orchid growing as an epiphyte on a mango branch or barnacles on a whale’s back?', '{"A":"Commensalism","B":"Mutualism","C":"Amensalism","D":"Proto-cooperation"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', 'Commensalism benefits one partner (+) while the host remains unaffected (0).', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000036', '65d29b56-2011-2007-0000-000000000001', 'In Verhulst-Pearl Logistic growth equation dN/dt = rN[(K - N)/K], when N equals carrying capacity K, population growth rate dN/dt becomes:', '{"A":"Zero (asymptote phase)","B":"Maximum possible","C":"Negative","D":"Equal to rK"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', '(K-K)/K = 0 => dN/dt = 0.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000037', '65d29b56-2011-2007-0000-000000000002', 'In which ecosystem is the Ecological Pyramid of BIOMASS generally inverted?', '{"A":"Marine / Sea ecosystem (small phytoplankton supporting large fishes)","B":"Grassland ecosystem","C":"Tropical forest","D":"Cropland ecosystem"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', 'Standing crop biomass of short-lived phytoplankton is far less than zooplankton/fish biomass; Energy pyramid is ALWAYS upright.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000038', '65d29b56-2011-2007-0000-000000000002', 'If 20,000 J of solar/plant energy is trapped by producers (T1), how much energy reaches Tertiary Consumers (T4 — Lion) by Lindeman’s 10% Law?', '{"A":"20 J","B":"200 J","C":"2 J","D":"2000 J"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', 'T1 (20,000) -> T2 (2,000) -> T3 (200) -> T4 (20 J).', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000039', '65d29b56-2011-2007-0000-000000000002', 'Among the "Evil Quartet" causes of biodiversity losses, which is the MOST important single driver driving species extinction?', '{"A":"Habitat loss and fragmentation","B":"Alien species invasions","C":"Co-extinctions","D":"Over-exploitation"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', 'NCERT Ecology XII: Habitat loss & fragmentation (tropical rainforests shrinking from 14% to 6%) is the primary cause.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000040', '65d29b56-2011-2002-0000-000000000002', '[NMC Added Family] Superior tricarpellary? No — Gramineae (Poaceae — Wheat/Maize) features spikelet inflorescence, lodicules perianth and which fruit type?', '{"A":"Caryopsis (pericarp fused with seed coat)","B":"Siliqua","C":"Legume","D":"Capsule"}'::jsonb, 'A', 'MCQ', 'Botany', 'Morphology & Anatomy', 4, 1.00, 'NMC_SYNCED', 'Caryopsis grain with versatile anthers & feathery stigma defines Gramineae/Poaceae.', 'MEDIUM', 'NMC 2026 Syllabus', true),
    ('30100101-0000-4000-8000-000000000041', '65d29b56-2011-2001-0000-000000000003', 'Which plant group is known as "Amphibians of the Plant Kingdom" because they live on soil but depend on external water for sexual reproduction?', '{"A":"Bryophytes","B":"Pteridophytes","C":"Gymnosperms","D":"Chlorophyceae"}'::jsonb, 'A', 'MCQ', 'Botany', 'Diversity in Living World', 4, 1.00, 'NMC_SYNCED', 'Bryophyte antherozoids swim in water film to reach archegonial egg.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000042', '65d29b56-2011-2004-0000-000000000001', 'Total ATP and NADPH required to synthesize ONE glucose molecule (6 CO₂ fixed) via the C3 Calvin Cycle is:', '{"A":"18 ATP and 12 NADPH","B":"30 ATP and 12 NADPH","C":"12 ATP and 18 NADPH","D":"3 ATP and 2 NADPH"}'::jsonb, 'A', 'MCQ', 'Botany', 'Plant Physiology', 4, 1.00, 'NMC_SYNCED', 'Per CO₂ = 3 ATP + 2 NADPH => × 6 turns = 18 ATP + 12 NADPH.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000043', '65d29b56-2011-2005-0000-000000000001', 'Outer exine of pollen grain resists high temperature, strong acids and alkali degradation due to:', '{"A":"Sporopollenin","B":"Cellulose & Pectin (Intine)","C":"Chitin","D":"Suberin"}'::jsonb, 'A', 'MCQ', 'Botany', 'Sexual Reproduction Plants', 4, 1.00, 'NMC_SYNCED', 'Sporopollenin is the most resistant organic biological polymer known; germ pores lack it.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000044', '65d29b56-2011-2006-0000-000000000002', 'In the DNA fingerprinting technique developed by Alec Jeffreys, tandemly repeated mini-satellite sequences used as probes are:', '{"A":"VNTR (Variable Number of Tandem Repeats)","B":"Exons","C":"Okazaki fragments","D":"Plasmids"}'::jsonb, 'A', 'MCQ', 'Botany', 'Genetics & Molecular', 4, 1.00, 'NMC_SYNCED', 'VNTR belongs to mini-satellite DNA showing high polymorphism between individuals.', 'EASY', 'NEET PYQ', true),
    ('30100101-0000-4000-8000-000000000045', '65d29b56-2011-2007-0000-000000000002', 'Which of the following is an EX-SITU biodiversity conservation strategy (off-site)?', '{"A":"Cryopreservation, Seed banks & Zoological parks","B":"Biosphere reserves","C":"Sacred groves","D":"National parks"}'::jsonb, 'A', 'MCQ', 'Botany', 'Ecology & Biodiversity', 4, 1.00, 'NMC_SYNCED', 'National parks, sanctuaries, biosphere reserves & sacred groves are In-situ; Cryopreservation/botanical gardens/zoos are Ex-situ.', 'EASY', 'NEET PYQ', true);
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('30100201-0000-4000-8000-000000000001', '65d29b56-2012-2001-0000-000000000001', 'Organ-system level, bilateral symmetry, pseudocoelomate body cavity and muscular pharynx characterize Phylum:', '{"A":"Aschelminthes (e.g. Ascaris, Wuchereria)","B":"Platyhelminthes","C":"Annelida","D":"Echinodermata"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Aschelminthes are the ONLY pseudocoelomate phylum; Platyhelminthes are acoelomate; Annelida onwards are coelomate.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000002', '65d29b56-2012-2001-0000-000000000001', 'Water vascular system (distinct from canal system of sponges) aiding locomotion, food capture & respiration defines:', '{"A":"Echinodermata (Asterias, Echinus)","B":"Porifera","C":"Cnidaria","D":"Mollusca"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Porifera has Water Canal System (choanocytes); Echinodermata has Water Vascular System.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000003', '65d29b56-2012-2001-0000-000000000001', 'Radula (file-like rasping organ for feeding) is present in Phylum:', '{"A":"Mollusca","B":"Arthropoda","C":"Hemichordata","D":"Ctenophora"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Molluscs have mantle cavity with feather-like gills and radula rasping organ.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000004', '65d29b56-2012-2001-0000-000000000002', '[NMC Retained Cockroach] Select the correct digestive tract sequence of Cockroach (Periplaneta americana):', '{"A":"Pharynx -> Oesophagus -> Crop -> Gizzard -> Ileum -> Colon -> Rectum","B":"Crop -> Gizzard -> Oesophagus -> Rectum","C":"Gizzard -> Crop -> Mesenteron","D":"Pharynx -> Gizzard -> Crop -> Colon"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Crop stores food; Gizzard (proventriculus) has 6 chitinous teeth to grind food; Hepatic caecae sit at foregut-midgut junction.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000005', '65d29b56-2012-2001-0000-000000000002', '[NMC Retained Frog] In adult Frogs (Rana tigrina), vascularized skin acts as the EXCLUSIVE respiratory organ during:', '{"A":"Hibernation and Aestivation (under soil/mud)","B":"Jumping on land","C":"Croaking in rain","D":"Metamorphosis tadpole gill stage"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Frogs respire via lungs + skin on land, skin in water, and exclusively via moist skin (cutaneous) during hibernation/aestivation.', 'EASY', 'NEET 2024', true),
    ('30100201-0000-4000-8000-000000000006', '65d29b56-2012-2001-0000-000000000002', 'Which cell junction stops substances from leaking across epithelial tissue sheets?', '{"A":"Tight junctions","B":"Gap junctions","C":"Desmosomes (Adhering junctions)","D":"Plasmodesmata"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Tight = prevent leakage; Adhering = cement neighbouring cells; Gap = rapid cytoplasmic ion transfer.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000007', '65d29b56-2012-2002-0000-000000000001', 'Which protein is the MOST abundant protein in the whole biosphere vs the most abundant protein in the animal world?', '{"A":"RuBisCO (Biosphere) and Collagen (Animal world)","B":"Collagen and RuBisCO","C":"Myosin and Actin","D":"Insulin and Haemoglobin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Biomolecules & Enzymes', 4, 1.00, 'NMC_SYNCED', 'NCERT Ch 9 Box check: Collagen = most abundant animal protein; RuBisCO = most abundant biosphere protein.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000008', '65d29b56-2012-2002-0000-000000000001', 'Competitive inhibition of succinate dehydrogenase by malonate raises apparent Km while leaving Vmax:', '{"A":"Unchanged","B":"Halved","C":"Doubled","D":"Zero"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Biomolecules & Enzymes', 4, 1.00, 'NMC_SYNCED', 'In competitive inhibition, substrate outcompetes inhibitor at high [S] => Vmax remains constant, Km increases.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000009', '65d29b56-2012-2002-0000-000000000001', 'Which organic secondary metabolites serve as NCERT classic examples of Polymeric Substances and Lectins respectively?', '{"A":"Rubber/Gums/Cellulose and Concanavalin A","B":"Morphine and Codeine","C":"Abrin and Ricin","D":"Vinblastin and Curcumin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Biomolecules & Enzymes', 4, 1.00, 'NMC_SYNCED', 'Concanavalin A = Lectin; Abrin/Ricin = Toxins; Morphine/Codeine = Alkaloids.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000010', '65d29b56-2012-2003-0000-000000000001', 'Volume of air remaining in human lungs even after the most forcible expiration (approx. 1100–1200 mL) is:', '{"A":"Residual Volume (RV)","B":"Expiratory Reserve Volume (ERV)","C":"Tidal Volume (TV)","D":"Functional Residual Capacity (FRC)"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', 'RV ≈ 1100–1200 mL prevents lung collapse; FRC = ERV + RV.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000011', '65d29b56-2012-2003-0000-000000000001', 'Approximately what percentage of CO₂ in human blood is transported in the form of bicarbonate (HCO₃⁻) ions?', '{"A":"70 %","B":"20–25 % (carbamino-Hb)","C":"7 % (dissolved in plasma)","D":"97 %"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', '70% as bicarbonate via carbonic anhydrase, 20–25% as carbamino-Hb, ~7% dissolved in plasma.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000012', '65d29b56-2012-2003-0000-000000000002', 'Which heart sound ("LUB") is produced at the beginning of ventricular systole?', '{"A":"Closure of tricuspid and bicuspid (AV) valves","B":"Closure of semilunar valves","C":"Opening of AV valves","D":"Sinoatrial node firing"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', 'First sound LUB = AV valve closure; Second sound DUB = semilunar valve closure.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000013', '65d29b56-2012-2003-0000-000000000002', 'Incompatibility between Rh⁻ pregnant mother and Rh⁺ foetus during SECOND pregnancy causes Erythroblastosis foetalis, prevented by administering:', '{"A":"Anti-Rh antibodies to mother immediately after first delivery","B":"Rh+ blood transfusion before birth","C":"Anti-A serum to foetus","D":"Heparin injections"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', 'Anti-Rh IgG clears leaked Rh+ fetal RBCs before maternal memory B-cells sensitize.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000014', '65d29b56-2012-2004-0000-000000000001', 'Descending limb of Loop of Henle in a nephron is:', '{"A":"Permeable to water but almost impermeable to electrolytes (concentrates filtrate)","B":"Impermeable to water, permeable to NaCl","C":"Site of active bicarbonate secretion only","D":"Impermeable to both water and ions"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Descending = water permeable -> filtrate hypertonic; Ascending = water impermeable, NaCl exits -> filtrate hypotonic.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000015', '65d29b56-2012-2004-0000-000000000001', 'Which peptide hormone released by atrial heart walls acts as a powerful vasodilator and CHECK (negative feedback) on the RAAS mechanism?', '{"A":"ANF (Atrial Natriuretic Factor)","B":"Aldosterone","C":"ADH / Vasopressin","D":"Angiotensin II"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'High BP triggers ANF release -> vasodilation -> decreases renin/BP.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000016', '65d29b56-2012-2004-0000-000000000001', 'During skeletal muscle contraction, Ca²⁺ ions bind to which regulatory protein subunit to unmask active binding sites on Actin?', '{"A":"Troponin (TpC subunit)","B":"Myosin ATPase head","C":"Tropomyosin M-line","D":"Z-line elastic fibre"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Sarcoplasmic reticulum releases Ca²⁺ -> binds Troponin -> shifts tropomyosin -> myosin binds actin.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000017', '65d29b56-2012-2004-0000-000000000002', 'During resting membrane potential of a neuron (approx. -70 mV), the Na⁺-K⁺ pump actively transports:', '{"A":"3 Na⁺ outwards for every 2 K⁺ into the cell","B":"2 Na⁺ outwards for 3 K⁺ inwards","C":"Equal 2 Na⁺ and 2 K⁺ passively","D":"Cl⁻ inwards against potential"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Electrogenic ATP-driven 3 Na⁺ out / 2 K⁺ in maintains negative axoplasm polarity.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000018', '65d29b56-2012-2004-0000-000000000002', 'Exophthalmic goitre (Graves’ disease — protruded eyeballs, high BMR & weight loss) is caused by:', '{"A":"Hyperthyroidism (excess thyroid hormones)","B":"Hypothyroidism (cretinism)","C":"Addison’s disease","D":"Acromegaly"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Graves disease = Hyperthyroidism; Cretinism/Simple goitre = Hypothyroidism.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000019', '65d29b56-2012-2005-0000-000000000001', 'Rapid secretion of which pituitary hormone reaching peak mid-cycle (~Day 14) induces Graafian follicle rupture and ovulation?', '{"A":"LH (Luteinising Hormone — LH Surge)","B":"Oxytocin","C":"Progesterone","D":"Prolactin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'LH surge triggers ovulation and transforms ruptured Graafian follicle into progesterone-secreting Corpus Luteum.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000020', '65d29b56-2012-2005-0000-000000000001', 'Which ART technique transfers an embryo with MORE than 8 blastomeres directly into the uterus?', '{"A":"IUT (Intra Uterine Transfer)","B":"ZIFT (Zygote Intra Fallopian Transfer)","C":"GIFT (Gamete Intra Fallopian Transfer)","D":"ICSI"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'Up to 8 blastomeres -> ZIFT (into fallopian tube); > 8 blastomeres -> IUT (into uterus).', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000021', '65d29b56-2012-2005-0000-000000000002', 'Forelimbs of Whale, Bat, Cheetah and Human share identical anatomical bone pattern (humerus, radius, ulna) illustrating:', '{"A":"Homologous organs & Divergent evolution","B":"Analogous organs & Convergent evolution","C":"Atavism","D":"Founder genetic drift"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'Same structural origin + different functions = Homologous -> Divergent evolution.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000022', '65d29b56-2012-2005-0000-000000000002', 'In a population in Hardy-Weinberg equilibrium, frequency of dominant allele A is 0.6. Calculate frequency of heterozygous individuals (Aa):', '{"A":"0.48 (48 %)","B":"0.36","C":"0.16","D":"0.24"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'p = 0.6 => q = 0.4 => 2pq = 2 × 0.6 × 0.4 = 0.48.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000023', '65d29b56-2012-2006-0000-000000000001', 'Which infective stage of Plasmodium (Malaria parasite) enters human blood upon bite of female Anopheles mosquito?', '{"A":"Sporozoites","B":"Gametocytes","C":"Merozoites","D":"Haemozoin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'Infective form for human = Sporozoite; toxic pigment causing chill cycles on RBC rupture = Haemozoin.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000024', '65d29b56-2012-2006-0000-000000000001', 'Cyclosporin A (immunosuppressive drug in organ transplant) and Statins (blood-cholesterol lowering) are derived respectively from:', '{"A":"Trichoderma polysporum (fungus) and Monascus purpureus (yeast)","B":"Penicillium notatum and Streptococcus","C":"Aspergillus niger and Acetobacter aceti","D":"Saccharomyces cerevisiae and Lactobacillus"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'Cyclosporin A <- Trichoderma polysporum; Statins <- Monascus purpureus; Streptokinase clot buster <- Streptococcus.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000025', '65d29b56-2012-2006-0000-000000000002', 'In vector pBR322, ligating foreign DNA into the BamHI restriction site inactivates which selectable marker gene?', '{"A":"Tetracycline resistance gene (tetᴿ)","B":"Ampicillin resistance gene (ampᴿ)","C":"ori replication gene","D":"rop protein gene"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'BamHI & SalI sit inside tetᴿ; PstI & PvuI sit inside ampᴿ.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000026', '65d29b56-2012-2006-0000-000000000002', 'Which Bt crystal protein genes control COTTON BOLLWORMS vs CORN BORER respectively?', '{"A":"cryIAc & cryIIAb control Cotton bollworms; cryIAb controls Corn borer","B":"cryIAb controls Bollworms","C":"cryIAc controls Corn borer","D":"cryIIAb controls nematodes"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'Classic NCERT Ch 10 biotech line: cryIAc & cryIIAb -> cotton bollworms; cryIAb -> corn borer.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000027', '65d29b56-2012-2001-0000-000000000001', 'Which jawless vertebrate (Cyclostomata) is marine yet migrates to fresh water for spawning and dies within a few days?', '{"A":"Petromyzon (Lamprey)","B":"Scoliodon (Dog fish)","C":"Labeo (Rohu)","D":"Ichthyophis"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Cyclostomes (Petromyzon, Myxine) lack jaws/paired fins; larvae (ammocoete) return to ocean after metamorphosis.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000028', '65d29b56-2012-2001-0000-000000000002', '[NMC Retained Frog] Male frogs are distinguished externally from females by the presence of:', '{"A":"Sound-producing vocal sacs and copulatory pad on first digit of forelimb","B":"Webbed hind limbs only","C":"Tympanum behind eyes","D":"Cloacal aperture"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'NCERT Frog sexual dimorphism: Vocal sacs + copulatory (nuptial) pad on 1st digit of forelimbs.', 'EASY', 'NEET 2024', true),
    ('30100201-0000-4000-8000-000000000029', '65d29b56-2012-2002-0000-000000000001', 'Which class of enzymes (EC Class 3) catalyses hydrolysis of ester, ether, peptide and glycosidic bonds?', '{"A":"Hydrolases","B":"Transferases","C":"Lyases","D":"Ligases"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Biomolecules & Enzymes', 4, 1.00, 'NMC_SYNCED', 'EC 1 Oxidoreductase, EC 2 Transferase, EC 3 Hydrolase, EC 4 Lyase (no water!), EC 5 Isomerase, EC 6 Ligase.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000030', '65d29b56-2012-2003-0000-000000000002', 'In human blood coagulation cascade, inactive fibrinogen in plasma is converted into insoluble fibrin threads by:', '{"A":"Thrombin (formed from prothrombin via thrombokinase)","B":"Plasmin","C":"Heparin","D":"Albumin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', 'Thrombokinase (+ Ca²⁺) activates prothrombin -> thrombin -> converts soluble fibrinogen to insoluble fibrin clot.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000031', '65d29b56-2012-2004-0000-000000000001', 'Ball-and-socket synovial joint vs Hinge joint vs Saddle joint examples respectively are:', '{"A":"Shoulder (humerus+pectoral), Knee/Elbow, Carpal-metacarpal of thumb","B":"Atlas-axis, Knee, Skull sutures","C":"Pubic symphysis, Elbow, Wrist","D":"Shoulder, Atlas-axis, Knee"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Pivot = Atlas-Axis; Gliding = Carpals; Saddle = Carpal-metacarpal of thumb.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000032', '65d29b56-2012-2004-0000-000000000002', 'Statement I: Steroid hormones (cortisol, testosterone, oestradiol) interact with intracellular nuclear receptors.\nStatement II: Peptide hormones require second messengers like cAMP, IP₃ or Ca²⁺.', '{"A":"Both Statement I and Statement II are correct","B":"Statement I is correct, Statement II is incorrect","C":"Both Statements are incorrect","D":"Statement I is incorrect, Statement II is correct"}'::jsonb, 'A', 'STATEMENT', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Lipid-soluble steroids cross membrane to bind nuclear receptors; water-soluble peptide hormones act via membrane receptors & second messengers.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000033', '65d29b56-2012-2005-0000-000000000001', 'Which copper-releasing IUDs suppress sperm motility and fertilising capacity of sperms inside the uterus?', '{"A":"CuT, Cu7 and Multiload 375","B":"Lippes loop (non-medicated)","C":"Progestasert & LNG-20","D":"Saheli (non-steroidal pill)"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'CuT, Cu7, Multiload 375 = Copper IUDs; Progestasert & LNG-20 = Hormone-releasing IUDs.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000034', '65d29b56-2012-2005-0000-000000000002', 'Correct chronological human ancestor sequence by increasing cranial capacity is:', '{"A":"Australopithecines -> Homo habilis (650–800 cc) -> Homo erectus (900 cc) -> Neanderthal (1400 cc)","B":"Homo erectus -> Homo habilis -> Neanderthal","C":"Ramapithecus -> Neanderthal -> Homo erectus","D":"Homo habilis -> Australopithecines -> Homo erectus"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'Exact NCERT cranial volume progression: H. habilis 650–800cc -> H. erectus 900cc -> Neanderthal 1400cc.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000035', '65d29b56-2012-2006-0000-000000000001', 'Assertion (A): Active immunity is slow and takes time to give its full effective response.\nReason (R): Injection of preformed antibodies against snake venom confers rapid passive immunity.', '{"A":"Both A and R are true, and R does not explain why A is slow","B":"Both A and R are true and R is correct explanation of A","C":"A is true, R is false","D":"A is false, R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'Both NCERT facts are true individually: active requires host clonal expansion (slow), whereas anti-venom is passive immunity.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000036', '65d29b56-2012-2006-0000-000000000002', 'First clinical gene therapy (1990) was given to a 4-year-old girl suffering from deficiency of which enzyme?', '{"A":"Adenosine deaminase (ADA)","B":"Phenylalanine hydroxylase","C":"Hexosaminidase A","D":"α-1-antitrypsin"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'ADA enzyme is crucial for immune system function; engineered retrovirus introduced functional ADA cDNA into patient lymphocytes.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000037', '65d29b56-2012-2006-0000-000000000002', 'During gel electrophoresis, negatively charged DNA fragments separated on agarose gel are visualized after Ethidium Bromide staining under UV radiation as:', '{"A":"Bright orange-coloured bands","B":"Blue fluorescent bands","C":"Pink precipitates","D":"Green glowing bands"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'EtBr intercalates DNA and fluoresces bright orange under UV light.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000038', '65d29b56-2012-2001-0000-000000000001', 'Which class of Chordata exhibits air sacs connected to lungs supplementing respiration and pneumatic (hollow) long bones?', '{"A":"Aves (Birds)","B":"Reptilia","C":"Amphibia","D":"Chondrichthyes"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Class Aves has pneumatic ossified bones, 4-chambered heart, crop/gizzard & air sacs.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000039', '65d29b56-2012-2001-0000-000000000002', 'In Cockroach (Periplaneta), mushroom-shaped gland functioning as an accessory reproductive gland is present in:', '{"A":"6th–7th abdominal segments of male cockroach","B":"4th–6th abdominal segments of female","C":"Thorax only","D":"Malpighian tubules"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Animal Kingdom & Morphology', 4, 1.00, 'NMC_SYNCED', 'Mushroom gland in 6th–7th abdominal segments nourishes/stores spermatophores in male cockroaches.', 'MEDIUM', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000040', '65d29b56-2012-2002-0000-000000000001', 'Which polysaccharide forms the exoskeleton of arthropods (like crabs and insects) and fungal cell walls?', '{"A":"Chitin (complex homopolymer of N-acetylglucosamine)","B":"Inulin","C":"Glycogen","D":"Cellulose"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Biomolecules & Enzymes', 4, 1.00, 'NMC_SYNCED', 'Chitin is an amino-sugar polymer; Inulin is a polymer of fructose.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000041', '65d29b56-2012-2003-0000-000000000001', 'Primary respiratory rhythm centre regulating inspiration and expiration is situated in which brain region?', '{"A":"Medulla oblongata","B":"Cerebellum","C":"Hypothalamus","D":"Pons pneumotaxic alone"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology I', 4, 1.00, 'NMC_SYNCED', 'Medulla houses respiratory rhythm centre; Pons houses pneumotaxic centre that moderates it.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000042', '65d29b56-2012-2004-0000-000000000002', 'Part of the human brain containing neurosecretory cells, thermoregulation centre, and centres for urge of eating and drinking is:', '{"A":"Hypothalamus","B":"Corpus callosum","C":"Pons","D":"Medulla"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Human Physiology II', 4, 1.00, 'NMC_SYNCED', 'Hypothalamus is body thermostat and master endocrine-neural integrator.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000043', '65d29b56-2012-2005-0000-000000000001', 'During human spermatogenesis, how many spermatozoa are produced from 100 primary spermatocytes vs ova from 100 primary oocytes?', '{"A":"400 spermatozoa and 100 ova","B":"200 spermatozoa and 200 ova","C":"400 spermatozoa and 400 ova","D":"100 spermatozoa and 100 ova"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Reproduction & Evolution', 4, 1.00, 'NMC_SYNCED', 'Each primary spermatocyte yields 4 sperms; each primary oocyte yields 1 functional ovum + polar bodies.', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000044', '65d29b56-2012-2006-0000-000000000001', 'Diagnostic confirmatory test commonly used to detect HIV / AIDS by enzyme-linked immunosorbent assay is:', '{"A":"ELISA (confirmatory Western Blot)","B":"Widal test (Typhoid)","C":"Mantoux test","D":"Schick test"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'ELISA detects HIV antibodies/antigens; Widal confirms Typhoid (Salmonella typhi).', 'EASY', 'NEET PYQ', true),
    ('30100201-0000-4000-8000-000000000045', '65d29b56-2012-2006-0000-000000000002', 'In the recombinant human insulin ("Humulin") prepared by Eli Lilly (1983), which chain present in natural pro-insulin is REMOVED during maturation?', '{"A":"C-peptide chain (leaving A and B chains linked by disulphide bridges)","B":"A-peptide chain","C":"B-peptide chain","D":"Leader N-terminal histidine tag"}'::jsonb, 'A', 'MCQ', 'Zoology', 'Health & Biotechnology', 4, 1.00, 'NMC_SYNCED', 'Pro-insulin has A, B, and C chains; Eli Lilly produced A and B chains separately in E. coli and linked them via disulphide bonds.', 'EASY', 'NEET PYQ', true);
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified)
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('30100301-0000-4000-8000-000000000036', '65d29b56-2013-2009-0000-000000000001', 'Deficiency of which water-soluble vitamin causes pernicious anaemia?', '{"A":"Vitamin B₁₂ (Cyanocobalamin)","B":"Vitamin C (Ascorbic acid)","C":"Vitamin B₁ (Thiamine)","D":"Vitamin K"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NMC_SYNCED', 'NCERT Chemistry XII Ch 10 Table 10.3: Vitamin B12 -> Pernicious anaemia; B1 -> Beri-beri; C -> Scurvy.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000037', '65d29b56-2013-2006-0000-000000000001', 'Why do transition metals (3d series) and their compounds exhibit strong catalytic activity?', '{"A":"Variable oxidation states & ability to form intermediate complexes","B":"High atomic mass only","C":"Completely filled d¹⁰ subshells","D":"Diamagnetic behaviour"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NMC_SYNCED', 'Available d-orbitals allow multiple oxidation states & intermediate adsorption (e.g. V₂O₅, Fe, Ni).', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000038', '65d29b56-2013-2005-0000-000000000001', 'A catalyst increases the rate of a chemical reaction primarily by:', '{"A":"Lowering the activation energy barrier (Ea) via an alternate path","B":"Increasing ΔH of reaction","C":"Shifting equilibrium constant Keq towards products","D":"Increasing enthalpy of reactants"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NMC_SYNCED', 'Catalyst lowers Ea without changing ΔG, ΔH, or equilibrium constant K.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000039', '65d29b56-2013-2001-0000-000000000001', 'Which set of quantum numbers (n, l, m, s) is IMPOSSIBLE for an electron in a multi-electron atom?', '{"A":"n = 3, l = 3, m = 0, s = +1/2","B":"n = 3, l = 2, m = -2, s = -1/2","C":"n = 4, l = 0, m = 0, s = +1/2","D":"n = 2, l = 1, m = +1, s = -1/2"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NMC_SYNCED', 'Azimuthal quantum number l ranges strictly from 0 to (n - 1), so l cannot equal n.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000040', '65d29b56-2013-2003-0000-000000000001', 'Human red blood cells (RBCs) shrink (crenation) when placed in which type of NaCl aqueous solution?', '{"A":"Hypertonic (> 0.9% w/v NaCl)","B":"Isotonic (0.9% w/v NaCl)","C":"Hypotonic (< 0.9% w/v NaCl)","D":"Pure distilled water"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NMC_SYNCED', '0.9% w/v NaCl is isotonic with RBC fluid; >0.9% causes exosmosis (shrinking).', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000041', '65d29b56-2013-2008-0000-000000000001', 'Carbylamine test (CHCl₃ + alc. KOH) yields foul-smelling isocyanides exclusively with:', '{"A":"Primary (1°) aliphatic and aromatic amines","B":"Secondary (2°) amines only","C":"Tertiary (3°) amines","D":"Amides and nitriles"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NMC_SYNCED', 'Only 1° amines (R-NH₂ & Ar-NH₂) respond positively to Carbylamine test.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000042', '65d29b56-2013-2002-0000-000000000001', 'Hydrogen bond strength is MAXIMUM in which compound?', '{"A":"HF (Hydrogen Fluoride)","B":"HCl","C":"HBr","D":"CH₄"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NMC_SYNCED', 'Highest electronegativity of Fluorine produces strongest individual H-F···H hydrogen bond.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000043', '65d29b56-2013-2004-0000-000000000001', 'Adding an inert gas at CONSTANT VOLUME to an equilibrium N₂ + 3H₂ ⇌ 2NH₃:', '{"A":"Produces zero shift in equilibrium position","B":"Shifts equilibrium towards NH₃","C":"Shifts equilibrium backwards","D":"Increases Kc"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NMC_SYNCED', 'At constant volume, molar concentrations / partial pressures of reacting gases remain unchanged.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000044', '65d29b56-2013-2007-0000-000000000001', 'Which alkene gives ONLY acetone (propanone) on reductive ozonolysis?', '{"A":"2,3-dimethylbut-2-ene","B":"2-methylpropene","C":"But-2-ene","D":"Propene"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NMC_SYNCED', '(CH₃)₂C=C(CH₃)₂ breaks cleanly into 2 molecules of (CH₃)₂C=O.', 'EASY', 'NEET PYQ', true),
    ('30100301-0000-4000-8000-000000000045', '65d29b56-2013-2009-0000-000000000001', 'Brown Ring Test for Nitrate (NO₃⁻) ion forms which coloured iron complex at the acid junction?', '{"A":"[Fe(H₂O)₅(NO)]²⁺","B":"Fe₄[Fe(CN)₆]₃","C":"[Fe(CN)₅NOS]⁴⁻","D":"[Fe(SCN)₂]⁺"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NMC_SYNCED', 'Fresh FeSO₄ reduces NO₃⁻ -> NO, binding Fe²⁺ to give brown ring complex [Fe(H₂O)₅(NO)]²⁺.', 'MEDIUM', 'NEET PYQ', true);
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified)
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('30100401-0000-4000-8000-000000000036', '65d29b56-2014-2001-0000-000000000001', '[Unit 20 Experimental] A screw gauge has pitch 0.5 mm and 50 divisions on its circular scale. Its Least Count is:', '{"A":"0.01 mm (0.001 cm)","B":"0.1 mm","C":"0.05 mm","D":"0.001 mm"}'::jsonb, 'A', 'MCQ', 'Physics', 'Units & Experimental Skills', 4, 1.00, 'NMC_SYNCED', 'LC = Pitch / N = 0.5 mm / 50 = 0.01 mm = 0.001 cm.', 'EASY', 'NEET 2024', true),
    ('30100401-0000-4000-8000-000000000037', '65d29b56-2014-2015-0000-000000000001', 'Ratio of nuclear densities of ¹²C and ⁵⁶Fe nuclei is:', '{"A":"1 : 1 (Independent of Mass Number A)","B":"12 : 56","C":"(12/56)^(1/3)","D":"56 : 12"}'::jsonb, 'A', 'MCQ', 'Physics', 'Modern Physics & Semiconductors', 4, 1.00, 'NMC_SYNCED', 'Since V ∝ R³ ∝ A, density = M/V is nearly identical (~2.3×10¹⁷ kg/m³) for all nuclei.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000038', '65d29b56-2014-2014-0000-000000000001', 'Critical angle for total internal reflection at glass-air interface if refractive index μ = √2 is:', '{"A":"45°","B":"30°","C":"60°","D":"90°"}'::jsonb, 'A', 'MCQ', 'Physics', 'Optics', 4, 1.00, 'NMC_SYNCED', 'sin(i_c) = 1/μ = 1/√2 => i_c = 45°.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000039', '65d29b56-2014-2013-0000-000000000001', 'Which electromagnetic waves possess the SHORTEST wavelength and HIGHEST photon energy (used to destroy cancer cells)?', '{"A":"Gamma rays (γ-rays)","B":"X-rays","C":"Ultraviolet rays","D":"Microwaves"}'::jsonb, 'A', 'MCQ', 'Physics', 'EMI & AC', 4, 1.00, 'NMC_SYNCED', 'EM wavelength decreases: Radio > Micro > IR > Visible > UV > X-ray > Gamma.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000040', '65d29b56-2014-2015-0000-000000000001', 'In an ideal p-n junction diode under REVERSE bias, the width of the depletion layer:', '{"A":"Increases and potential barrier rises","B":"Decreases and potential barrier drops","C":"Reduces to zero","D":"Remains unaltered"}'::jsonb, 'A', 'MCQ', 'Physics', 'Modern Physics & Semiconductors', 4, 1.00, 'NMC_SYNCED', 'Reverse polarity pulls majority carriers away from the junction, widening the depletion zone.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000041', '65d29b56-2014-2006-0000-000000000001', 'Escape velocity from Earth’s surface is v_e = 11.2 km/s. For a planet with DOUBLE Earth’s mass and DOUBLE Earth’s radius, escape speed equals:', '{"A":"11.2 km/s (Unchanged)","B":"22.4 km/s","C":"5.6 km/s","D":"15.8 km/s"}'::jsonb, 'A', 'MCQ', 'Physics', 'Gravitation', 4, 1.00, 'NMC_SYNCED', 'v_e = √(2GM/R) => ratio M/R stays constant (2/2 = 1) => 11.2 km/s.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000042', '65d29b56-2014-2009-0000-000000000001', 'A second’s pendulum (T = 2 s on Earth) is carried to a planet where g'' = g/4. Its new time period becomes:', '{"A":"4 s","B":"1 s","C":"2 s","D":"8 s"}'::jsonb, 'A', 'MCQ', 'Physics', 'SHM & Waves', 4, 1.00, 'NMC_SYNCED', 'T ∝ 1/√g => dividing g by 4 doubles T from 2 s to 4 s.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000043', '65d29b56-2014-2008-0000-000000000001', 'According to Wien’s displacement law, peak wavelength λ_m radiated by a blackbody at Kelvin temperature T satisfies:', '{"A":"λ_m · T = constant (blue stars are hotter than red stars)","B":"λ_m / T = constant","C":"λ_m ∝ T⁴","D":"Independent of T"}'::jsonb, 'A', 'MCQ', 'Physics', 'Thermal Physics & KTG', 4, 1.00, 'NMC_SYNCED', 'Higher temperature shifts peak emission towards shorter blue/violet wavelengths (λ_m T = b).', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000044', '65d29b56-2014-2010-0000-000000000001', 'Force between two parallel long straight conductors carrying EQUAL currents in the SAME direction is:', '{"A":"Attractive","B":"Repulsive","C":"Zero","D":"Perpendicular to plane"}'::jsonb, 'A', 'MCQ', 'Physics', 'Moving Charges & Magnetism', 4, 1.00, 'NMC_SYNCED', 'Parallel same-direction currents attract; opposite-direction currents repel.', 'EASY', 'NEET PYQ', true),
    ('30100401-0000-4000-8000-000000000045', '65d29b56-2014-2004-0000-000000000001', 'Two bodies with identical kinetic energy have masses 1 kg and 4 kg. Ratio of magnitudes of their linear momenta (p₁ : p₂) is:', '{"A":"1 : 2","B":"1 : 4","C":"2 : 1","D":"1 : 1"}'::jsonb, 'A', 'MCQ', 'Physics', 'Work Energy Power', 4, 1.00, 'NMC_SYNCED', 'p = √(2mK) => with equal K, p₁/p₂ = √(1/4) = 1 : 2.', 'EASY', 'NEET PYQ', true);
