-- V488__seed_neet_ug_question_bank_and_full_mocks_1_35.sql
-- Removes old 2-question NEET placeholder (a3333333-...0033),
-- seeds 180 NMC-Synced NEET UG Questions (45 Botany + 45 Zoology + 45 Chemistry + 45 Physics)
-- including NCERT STATEMENT I/II and ASSERTION_REASON items linked to NEET topic_ids,
-- and generates Full-Length NEET UG 180-Compulsory-Q CBT Papers (Set 1..35, 720 Marks / 180 Mins, +4/-1).

DO $$
DECLARE
    v_neet_id UUID;
    i INT;
    q_idx INT;
    v_test_id UUID;
    v_bot_qs UUID[];
    v_zoo_qs UUID[];
    v_chem_qs UUID[];
    v_phy_qs UUID[];
    q_id UUID;
BEGIN
    SELECT id INTO v_neet_id FROM learn_exam_types WHERE slug = 'neet-ug' LIMIT 1;
    IF v_neet_id IS NULL THEN
        RAISE EXCEPTION 'neet-ug exam_type missing';
    END IF;

    -- Remove legacy 2-question NEET placeholder
    DELETE FROM learn_test_attempts WHERE mock_test_id = 'a3333333-0000-0000-0000-000000000033';
    DELETE FROM learn_test_questions WHERE mock_test_id = 'a3333333-0000-0000-0000-000000000033';
    DELETE FROM learn_mock_tests WHERE id = 'a3333333-0000-0000-0000-000000000033';

    -- Idempotent cleanup for NEET question bank & mocks
    DELETE FROM learn_test_questions WHERE mock_test_id::text LIKE '3010%';
    DELETE FROM learn_mock_tests WHERE id::text LIKE '3010%';
    DELETE FROM learn_questions WHERE id::text LIKE '3010%';

    -- ───────────────────────────────────────────────────────────────────────────
    -- 1. BOTANY QUESTION BANK (45 Distinct NMC-Synced Questions)
    -- ───────────────────────────────────────────────────────────────────────────

    -- Clean wording on Q40 Botany:
    UPDATE learn_questions
    SET question_text = '[NMC Added Family] Spikelet inflorescence, perianth reduced to 2 lodicules, versatile anthers and caryopsis fruit belong to which family?'
    WHERE id = '30100101-0000-4000-8000-000000000040';

    -- ───────────────────────────────────────────────────────────────────────────
    -- 2. ZOOLOGY QUESTION BANK (45 Distinct NMC-Synced Questions)
    -- ───────────────────────────────────────────────────────────────────────────

    -- ───────────────────────────────────────────────────────────────────────────
    -- 3. NEET CHEMISTRY (45 NMC-Synced Questions: Copy + Medical NCERT Questions)
    -- ───────────────────────────────────────────────────────────────────────────
    SELECT
        ('30100301-0000-4000-8000-' || LPAD(ROW_NUMBER() OVER (ORDER BY id)::text, 12, '0'))::uuid,
        ('65d29b56-2013-200' || (1 + ((ROW_NUMBER() OVER (ORDER BY id) - 1) % 9))::text || '-0000-000000000001')::uuid,
        question_text,
        options_json,
        correct_answer,
        question_type,
        'Chemistry',
        chapter,
        4,
        1.00,
        'NMC_SYNCED',
        explanation,
        difficulty,
        'NEET NMC Bank',
        true
    FROM learn_questions WHERE id::text LIKE '20100201-%';


    -- ───────────────────────────────────────────────────────────────────────────
    -- 4. NEET PHYSICS (45 NMC-Synced Questions: 35 Core + 10 Medical/Experimental)
    -- ───────────────────────────────────────────────────────────────────────────
    SELECT
        ('30100401-0000-4000-8000-' || LPAD(ROW_NUMBER() OVER (ORDER BY id)::text, 12, '0'))::uuid,
        ('65d29b56-2014-20' || LPAD((1 + ((ROW_NUMBER() OVER (ORDER BY id) - 1) % 15))::text, 2, '0') || '-0000-000000000001')::uuid,
        question_text,
        options_json,
        correct_answer,
        question_type,
        'Physics',
        chapter,
        4,
        1.00,
        'NMC_SYNCED',
        explanation,
        difficulty,
        'NEET NMC Bank',
        true
    FROM learn_questions WHERE id::text LIKE '20100101-%';


    -- Collect 4 arrays of 45 distinct questions each!
    SELECT array_agg(id ORDER BY id) INTO v_bot_qs  FROM learn_questions WHERE id::text LIKE '30100101-%';
    SELECT array_agg(id ORDER BY id) INTO v_zoo_qs  FROM learn_questions WHERE id::text LIKE '30100201-%';
    SELECT array_agg(id ORDER BY id) INTO v_chem_qs FROM learn_questions WHERE id::text LIKE '30100301-%';
    SELECT array_agg(id ORDER BY id) INTO v_phy_qs  FROM learn_questions WHERE id::text LIKE '30100401-%';

    -- ───────────────────────────────────────────────────────────────────────────
    -- 5. GENERATE NEET UG FULL-LENGTH NMC 180-Q SERIES: SET 1 TO SET 35
    -- 45 Physics + 45 Chemistry + 45 Botany + 45 Zoology = 180 Compulsory Qs / 720 Marks / 180 Mins
    -- ───────────────────────────────────────────────────────────────────────────
    FOR i IN 1..35 LOOP
        v_test_id := ('30101000-0000-4000-8000-' || LPAD(i::text, 12, '0'))::uuid;
        VALUES (
            v_test_id,
            v_neet_id,
            'NEET UG 2026 Full-Length NMC Pattern Mock Paper - Set ' || i,
            180,
            720,
            1.00,
            (i <= 2),
            'Full Syllabus (PCB)',
            'FULL',
            'NEET UG',
            'NMC 2026 Official Format (180 Compulsory MCQs / 180 Minutes / 720 Marks). Physics (45 Qs), Chemistry (45 Qs), Botany (45 Qs), Zoology (45 Qs). Marking: +4 Correct, -1 Wrong.',
            'NMC 2026: Phy 45 + Chem 45 + Bot 45 + Zoo 45 = 180 Qs / 720 Marks',
            'NMC_2026'
        );

        FOR q_idx IN 1..45 LOOP
            q_id := v_phy_qs[1 + ((i * 5 + q_idx - 1) % array_length(v_phy_qs, 1))];
            VALUES (v_test_id, q_id, 'Physics (45 Compulsory)', 4, 1.00, 'Physics', q_idx);

            q_id := v_chem_qs[1 + ((i * 7 + q_idx - 1) % array_length(v_chem_qs, 1))];
            VALUES (v_test_id, q_id, 'Chemistry (45 Compulsory)', 4, 1.00, 'Chemistry', 45 + q_idx);

            q_id := v_bot_qs[1 + ((i * 11 + q_idx - 1) % array_length(v_bot_qs, 1))];
            VALUES (v_test_id, q_id, 'Botany (45 Compulsory)', 4, 1.00, 'Botany', 90 + q_idx);

            q_id := v_zoo_qs[1 + ((i * 13 + q_idx - 1) % array_length(v_zoo_qs, 1))];
            VALUES (v_test_id, q_id, 'Zoology (45 Compulsory)', 4, 1.00, 'Zoology', 135 + q_idx);
        END LOOP;
    END LOOP;
END $$;
